INSERT INTO question (text, option1, option2, option3, option4, correct_option, explanation, category_id, difficulty) VALUES ('What is the function of an operating system?', 'Manage hardware and software resources', 'Provide internet access', 'Compile programs', 'Store files permanently', 1, 'An OS manages hardware resources and provides services to programs.', (SELECT id FROM category WHERE name='Computer' LIMIT 1), 'Medium');
INSERT INTO question (text, option1, option2, option3, option4, correct_option, explanation, category_id, difficulty) VALUES ('What does CPU stand for?', 'Central Processing Unit', 'Computer Personal Unit', 'Central Program Utility', 'Core Processing Unit', 1, 'CPU is the brain of the computer.', (SELECT id FROM category WHERE name='Computer' LIMIT 1), 'Medium');
INSERT INTO question (text, option1, option2, option3, option4, correct_option, explanation, category_id, difficulty) VALUES ('Which of the following is volatile memory?', 'RAM', 'ROM', 'Hard Disk', 'SSD', 1, 'RAM loses data when power is off.', (SELECT id FROM category WHERE name='Computer' LIMIT 1), 'Medium');
INSERT INTO question (text, option1, option2, option3, option4, correct_option, explanation, category_id, difficulty) VALUES ('What is the purpose of a compiler?', 'Convert high-level code to machine code', 'Execute programs directly', 'Manage memory allocation', 'Connect to the internet', 1, 'A compiler translates source code into machine-readable code.', (SELECT id FROM category WHERE name='Computer' LIMIT 1), 'Medium');
INSERT INTO question (text, option1, option2, option3, option4, correct_option, explanation, category_id, difficulty) VALUES ('Which layer of OSI model handles routing?', 'Network Layer', 'Data Link Layer', 'Transport Layer', 'Session Layer', 1, 'Network Layer (Layer 3) handles routing of packets.', (SELECT id FROM category WHERE name='Computer' LIMIT 1), 'Medium');
INSERT INTO question (text, option1, option2, option3, option4, correct_option, explanation, category_id, difficulty) VALUES ('What is a deadlock in operating systems?', 'Two processes waiting for each other indefinitely', 'A process using too much memory', 'A program that crashes', 'Slow CPU performance', 1, 'Deadlock occurs when processes are blocked waiting for each other.', (SELECT id FROM category WHERE name='Computer' LIMIT 1), 'Medium');
INSERT INTO question (text, option1, option2, option3, option4, correct_option, explanation, category_id, difficulty) VALUES ('Which data structure uses LIFO order?', 'Stack', 'Queue', 'LinkedList', 'Tree', 1, 'Stack uses Last In First Out order.', (SELECT id FROM category WHERE name='Computer' LIMIT 1), 'Medium');
INSERT INTO question (text, option1, option2, option3, option4, correct_option, explanation, category_id, difficulty) VALUES ('What is virtual memory?', 'Disk space used as RAM extension', 'A type of flash memory', 'Memory inside the CPU', 'Read-only memory', 1, 'Virtual memory uses disk to extend apparent RAM.', (SELECT id FROM category WHERE name='Computer' LIMIT 1), 'Medium');
INSERT INTO question (text, option1, option2, option3, option4, correct_option, explanation, category_id, difficulty) VALUES ('What does HTTP stand for?', 'HyperText Transfer Protocol', 'High Transfer Text Protocol', 'HyperText Transport Process', 'Home Transfer Text Protocol', 1, 'HTTP is used for web communication.', (SELECT id FROM category WHERE name='Computer' LIMIT 1), 'Medium');
INSERT INTO question (text, option1, option2, option3, option4, correct_option, explanation, category_id, difficulty) VALUES ('Which sorting algorithm has best average case complexity?', 'Quick Sort', 'Bubble Sort', 'Insertion Sort', 'Selection Sort', 1, 'Quick Sort has O(n log n) average case complexity.', (SELECT id FROM category WHERE name='Computer' LIMIT 1), 'Medium');
INSERT INTO question (text, option1, option2, option3, option4, correct_option, explanation, category_id, difficulty) VALUES ('What is the time complexity of binary search?', 'O(log n)', 'O(n)', 'O(n log n)', 'O(1)', 1, 'Binary search halves the space each step giving O(log n).', (SELECT id FROM category WHERE name='Computer' LIMIT 1), 'Hard');
INSERT INTO question (text, option1, option2, option3, option4, correct_option, explanation, category_id, difficulty) VALUES ('In networking, what does NAT stand for?', 'Network Address Translation', 'Node Access Terminal', 'Network Authentication Token', 'Null Address Table', 1, 'NAT translates private IPs to public IPs.', (SELECT id FROM category WHERE name='Computer' LIMIT 1), 'Hard');
INSERT INTO question (text, option1, option2, option3, option4, correct_option, explanation, category_id, difficulty) VALUES ('What is thrashing in operating systems?', 'Excessive paging causing severe performance degradation', 'CPU running too fast', 'Memory overflow error', 'Hard disk failure', 1, 'Thrashing occurs when more time is spent swapping pages than executing.', (SELECT id FROM category WHERE name='Computer' LIMIT 1), 'Hard');
INSERT INTO question (text, option1, option2, option3, option4, correct_option, explanation, category_id, difficulty) VALUES ('Which normal form eliminates transitive dependencies?', '3NF (Third Normal Form)', '1NF', '2NF', 'BCNF', 1, '3NF eliminates transitive functional dependencies.', (SELECT id FROM category WHERE name='Computer' LIMIT 1), 'Hard');
INSERT INTO question (text, option1, option2, option3, option4, correct_option, explanation, category_id, difficulty) VALUES ('What is the purpose of a semaphore in OS?', 'Synchronize access to shared resources', 'Allocate memory to processes', 'Schedule CPU tasks', 'Manage file permissions', 1, 'Semaphores control access to shared resources in concurrent programming.', (SELECT id FROM category WHERE name='Computer' LIMIT 1), 'Hard');
INSERT INTO question (text, option1, option2, option3, option4, correct_option, explanation, category_id, difficulty) VALUES ('What does ACID stand for in databases?', 'Atomicity, Consistency, Isolation, Durability', 'Access, Control, Integrity, Data', 'Async, Commit, Index, Distribute', 'Atomicity, Concurrency, Isolation, Data', 1, 'ACID properties ensure reliable database transactions.', (SELECT id FROM category WHERE name='Computer' LIMIT 1), 'Hard');
