INSERT INTO question (text, option1, option2, option3, option4, correct_option, explanation, category_id, difficulty) VALUES ('What is a B-tree used for?', 'Efficient database indexing', 'Binary search', 'Graph traversal', 'Sorting arrays', 1, 'B-trees are used in database indexing for fast lookups.', (SELECT id FROM category WHERE name='Computer' LIMIT 1), 'Hard');
INSERT INTO question (text, option1, option2, option3, option4, correct_option, explanation, category_id, difficulty) VALUES ('What is the difference between process and thread?', 'Process has own memory; thread shares memory within a process', 'Thread is always faster', 'Process is part of a thread', 'They are the same', 1, 'A process has own memory space; threads share memory within a process.', (SELECT id FROM category WHERE name='Computer' LIMIT 1), 'Hard');
INSERT INTO question (text, option1, option2, option3, option4, correct_option, explanation, category_id, difficulty) VALUES ('What does a hash collision mean?', 'Two keys produce the same hash value', 'A hash function fails', 'Data is corrupted', 'Hash table is full', 1, 'A collision is when two different inputs produce the same hash output.', (SELECT id FROM category WHERE name='Computer' LIMIT 1), 'Hard');
